const e=["Dieu","Connaissance","Magie","Religion","Force","Mystère"],t="Une vérité ne devient pas moins dangereuse parce qu'elle est vraie.",n="Dieu de la Connaissance",s=["Eone représente la Connaissance, une Force du Monde.","Il est associé à la recherche, à la mémoire, aux secrets, aux sciences et à la compréhension de ce qui échappe aux mortels.","Contrairement à certaines divinités, Eone ne représente pas une vérité particulière.","Il représente le fait de chercher à savoir.","Cela fait de lui une divinité profondément ambivalente.","La connaissance peut sauver une civilisation.","Elle peut également lui donner les moyens de la détruire."],r=[{label:"Domaines",value:"Connaissance"},{label:"Symboles",value:"Un œil, un livre ouvert, une clé, une étoile, une bibliothèque, une spirale"}],i=[{title:"Savoir n'est pas comprendre",title_border:"#e8553d",type:"text",content:["Les traditions d'Eone font une distinction importante entre connaître une chose et la comprendre.","Un mortel peut connaître l'existence d'une maladie sans savoir la soigner.","Il peut connaître l'existence d'un dieu sans comprendre sa nature.","Il peut découvrir une vérité sans être capable d'en accepter les conséquences.","Pour cette raison, les érudits d'Eone considèrent parfois l'ignorance comme préférable à certaines connaissances.","Mais ils reconnaissent également le danger inverse :","refuser de chercher ne rend pas une vérité moins réelle."]},{title:"La Bibliothèque",title_border:"#c2660a",type:"text",content:["Eone est souvent associé à une immense bibliothèque dont l'existence demeure incertaine.","Selon les traditions, elle contiendrait :"]},{title:"",type:"list",content:["Les connaissances perdues des civilisations disparues","Les véritables noms de certaines créatures","Des fragments des Temps Innommables","Des récits contradictoires sur les dieux","Des connaissances magiques oubliées","Des informations que les mortels ne devraient jamais découvrir"]},{title:"",type:"text",content:["Les récits divergent toutefois énormément sur son emplacement.","Certains affirment qu'elle existe quelque part en Asun.","D'autres pensent qu'elle se trouve en dehors du monde connu.","Certains érudits vont jusqu'à prétendre que la bibliothèque n'est pas un lieu, mais une manifestation de la Connaissance elle-même.","Aucune de ces hypothèses n'a été confirmée."]},{title:"Les secrets",title_border:"#6f9fd8",type:"text",content:["Eone est parfois représenté comme le gardien des secrets.","Cette interprétation est cependant trompeuse.","Eone ne semble pas chercher à empêcher les mortels de découvrir les vérités cachées.","Il semble plutôt considérer que toute connaissance doit pouvoir être recherchée.","Cela ne signifie pas qu'il offre les réponses.","Les fidèles d'Eone doivent chercher, expérimenter, comparer et parfois se tromper.","Un prêtre qui affirme connaître toutes les réponses est souvent considéré avec méfiance."]},{title:"Le culte d'Eone",title_border:"#e8553d",type:"text",content:["Les temples d'Eone sont généralement des lieux d'étude.","On y trouve :"]},{title:"",type:"list",content:["Des bibliothèques","Des observatoires","Des laboratoires","Des salles d'archives","Des cartes","Des instruments anciens","Des collections d'objets inconnus"]},{title:"",type:"text",content:["Ses prêtres sont souvent érudits, chercheurs, historiens, cartographes ou mages.","Certains parcourent le monde à la recherche de connaissances perdues.","D'autres passent leur vie à préserver ce qui existe déjà."]},{title:"Eone et les Histoires Perdues",title_border:"#c2660a",type:"text",content:["Eone possède une importance particulière dans l'étude des Histoires Perdues.","Les fragments anciens sont souvent contradictoires.","Un récit peut affirmer qu'un événement s'est déroulé d'une certaine manière, tandis qu'un autre raconte exactement l'inverse.","Pour les érudits d'Eone, cette contradiction n'est pas nécessairement un problème.","Elle est une information.","Elle signifie simplement que la vérité n'a pas encore été retrouvée."]},{title:"Eone et les autres dieux",title_border:"#6f9fd8",type:"text",content:["Eone entretient une relation particulière avec Riannedos.","Le Temps fait disparaître les civilisations.","La Connaissance cherche à préserver ce qu'elles ont laissé derrière elles.","Avec Quaara, son rapport est différent.","La Nature produit constamment de nouvelles choses à observer et à comprendre.","Avec Théomis, une tension existe parfois entre la conservation du savoir et son contrôle.","Et avec Neien, certaines traditions affirment qu'Eone fut parmi les premiers à comprendre que la transformation de sa Force ne pouvait pas être considérée comme un simple changement d'humeur divine.","Si cette histoire est vraie, Eone aurait été l'un des rares dieux à comprendre la gravité de ce qui était en train de se produire."]},{title:"Symboles",title_border:"#e8553d",type:"text",content:"Eone est généralement représenté par :"},{title:"",type:"list",content:["Un œil","Un livre ouvert","Une clé","Une étoile","Une bibliothèque","Une spirale"]},{title:"",type:"text",content:["L'œil est particulièrement courant.","Il ne symbolise pas le fait de voir.","Il symbolise le fait de chercher à voir ce qui est caché."]},{title:"Aujourd'hui",title_border:"#c2660a",type:"text",content:["Les chercheurs d'Asun continuent de prier Eone avant leurs expéditions.","Les historiens recherchent ses temples.","Les mages consultent ses archives.","Les explorateurs espèrent découvrir quelque chose qui n'a encore jamais été compris.","Mais certaines histoires racontent que ceux qui cherchent trop loin finissent par découvrir des choses qu'ils auraient préféré ne jamais connaître.","C'est peut-être la plus grande leçon attribuée à Eone :"]}],o=["Les Dieux","Les Forces","Les Forces du Monde","Riannedos","Théomis","Neien","Les Histoires Perdues","La Bibliothèque d'Eone","La Connaissance"],a={tags:e,citation:t,surname:n,presentation:s,infos:r,sections:i,related:o};export{t as citation,a as default,r as infos,s as presentation,o as related,i as sections,n as surname,e as tags};
